    if (String(g('sigValue')).trim() === '' || String(g('sigDia')).trim() === '') { toast('Enter systolic and diastolic'); return; }
    r = logBP(g('sigValue'), g('sigDia'), g('sigTime') || nowTime(), g('sigNotes'));
