  keys.sort();
  const points = keys.map((d) => ({ t: d, v: r1(num(dayTotals(APP_STATE.days[d])[nutrient])) }));
  const values = points.map((p) => p.v).slice().sort((a, b) => a - b);
  const n = values.length;
