  if (!name) return { ok: false, error: 'Name required.' };
  const g = clampNonNeg(spec.grams);
  if (!(g > 0)) return { ok: false, error: 'Grams must be positive.' };
  const MK = ['kcal', 'protein_g', 'fat_g', 'carb_g', 'fiber_g', 'soluble_fiber_g'];
