  if (!id) return null;
  const printed = normalizePrinted(r.printed);
  if (!printed.name) return null;                 // a medication always has a name, even "Unreadable label"
  const out = { id: id, source: MED_SOURCES.indexOf(r.source) >= 0 ? r.source : 'manual', printed: printed,
                created: /^\d{4}-\d{2}-\d{2}$/.test(String(r.created)) ? String(r.created) : '',
                fills: Array.isArray(r.fills) ? r.fills.map(normalizeFill).filter(Boolean) : [] };
  if (r.labelSetId != null && String(r.labelSetId) !== '') out.labelSetId = String(r.labelSetId);   // H5: the one document it points at
  // H8/D98: the DERIVED query term, stored beside `printed` and never in place of
  // it. Added to this normalizer in the same commit that introduced the field --
  // the allowlist trap has been walked into eight times, so it is the build's
  // first obligation rather than a note, and export -> restore is gated.
  const mq = normalizeQuery(r.query);
  if (mq) out.query = mq;
  // D105: additive provenance, so it joins the normalizer in the same edit that
  // introduces it. NO SCHEMA BUMP, and the reason is D29's asymmetry test
  // applied honestly: an older app strips this and nothing behaves differently
  // -- the term still goes out, the lookup still works. What is lost is the
  // RECORD of how the term was chosen, which is less information rather than a
  // wrong value. R31 drew that line: a bump is for a stripped field that makes a
  // number wrong, not for one that makes an audit thinner.
  const qp = normalizeQueryPick(r.query_pick);
  if (qp) out.query_pick = qp;
  // D111: joins the normalizer in the same edit that introduces it -- the
  // allowlist trap, tenth time of asking. No schema bump, by D105's reasoning:
  // an older app strips this and the term still goes out and the lookup still
  // works. What is lost is a claim about provenance, which then correctly reads
  // as NOT RECORDED rather than as a wrong value.
  const qs = normalizeQuerySrc(r.query_src);
  if (qs) out.query_src = qs;
  if (/^\d{4}-\d{2}-\d{2}$/.test(String(r.stopped))) out.stopped = String(r.stopped);
  if (r.ai_identity != null && String(r.ai_identity) !== '') out.ai_identity = String(r.ai_identity);
  const alts = normalizeAltList(r.ai_alts);
  if (alts) out.ai_alts = alts;
