  let done = false;
  if (box && box.offsetParent !== null) {
    try { box.focus(); box.select(); try { box.setSelectionRange(0, LABEL_TEMPLATE.length); } catch (e) {} done = document.execCommand('copy'); } catch (e) { done = false; }
  }
